{"command":"cat > main.go <<'EOF'
package main

import (
    "embed"
    "errors"
    "fmt"
    "io"
    "os"
    "path/filepath"
    "sort"
    "strconv"
    "strings"
    "syscall"
    "time"
)

// The text resources describe the command-line interface, including the
// completion scripts emitted by the completions command.
//go:embed cli_text/*.txt
var interfaceText embed.FS

const version = "2.32.2"
const rootUsage = "dua [FLAGS] [OPTIONS] [SUBCOMMAND] [INPUT]..."
const moreHelp = "For more information, try '--help'.\n"
var program = filepath.Base(os.Args[0])

var formats = []string{"metric", "binary", "bytes", "gb", "gib", "mb", "mib"}
var shells = []string{"bash", "elvish", "fish", "powershell", "zsh"}

type options struct {
    command string
    inputs []string
    threads uint64
    format string
    apparent, countLinks, stay bool
    ignore []string
    logFile string
    logSet bool
    stats, noSort, noTotal, noEntryCheck bool
}

type optionSpec struct {
    long, short, value string
    repeat bool
}
var rootOptions = []optionSpec{
    {"threads", "t", "THREADS", false},
    {"format", "f", "FORMAT", false},
    {"apparent-size", "A", "", false},
    {"count-hard-links", "l", "", false},
    {"stay-on-filesystem", "x", "", false},
    {"ignore-dirs", "i", "IGNORE_DIRS", true},
    {"log-file", "", "LOG_FILE", false},
    {"help", "h", "", false},
    {"version", "V", "", false},
}
func specifications(command string) []optionSpec {
    switch command {
    case "aggregate":
        return []optionSpec{{"stats", "", "", false}, {"no-sort", "", "", false}, {"no-total", "", "", false}, {"help", "h", "", false}}
    case "interactive":
        return []optionSpec{{"no-entry-check", "e", "", false}, {"help", "h", "", false}}
    case "completions":
        return []optionSpec{{"help", "h", "", false}}
    }
    return rootOptions
}
func usage(command string) string {
    switch command {
    case "aggregate", "interactive": return program+" "+command+" [OPTIONS] [INPUT]..."
    case "completions": return program+" completions <SHELL>"
    case "help": return program+" help [COMMAND]..."
    }
    return rootUsage
}
func optionName(s optionSpec) string {
    name := "--"+s.long
    if s.value != "" { name += " <"+s.value+">" }
    return name
}
func cliError(body, use string) {
    fmt.Fprint(os.Stderr, "error: "+body+"\n\n")
    if use != "" { fmt.Fprint(os.Stderr, "Usage: "+use+"\n\n") }
    fmt.Fprint(os.Stderr, moreHelp)
    os.Exit(2)
}
func printHelp(command string, long bool) {
    name := "help-"+command+".txt"
    if command == "" {
        if long { name="help-long.txt" } else { name="help-short.txt" }
    }
    b, _ := interfaceText.ReadFile("cli_text/"+name)
    text := strings.ReplaceAll(string(b), "Usage: executable ", "Usage: "+program+" ")
    fmt.Print(text)
}
func canonicalCommand(s string) string {
    switch s {case "i", "interactive": return "interactive"; case "a", "aggregate": return "aggregate"; case "help", "completions":return s}
    return ""
}

// Similarity is used only for friendly command-line spelling suggestions.
func similarity(a, b string) float64 {
    x, y := []rune(a), []rune(b)
    if a == b {return 1}
    if len(x)==0 || len(y)==0 {return 0}
    n:=len(x);if len(y)>n {n=len(y)}
    window:=n/2-1;if window<0 {window=0}
    mx,my:=make([]bool,len(x)),make([]bool,len(y))
    m:=0
    for i,c:=range x {
        start:=i-window;if start<0 {start=0};end:=i+window+1;if end>len(y){end=len(y)}
        for j:=start;j<end;j++ { if !my[j] && c==y[j] {mx[i]=true;my[j]=true;m++;break} }
    }
    if m==0{return 0}
    j,t:=0,0
    for i:=range x {if mx[i] {for !my[j]{j++};if x[i]!=y[j]{t++};j++}}
    score:=(float64(m)/float64(len(x))+float64(m)/float64(len(y))+(float64(m)-float64(t)/2)/float64(m))/3
    if score>0.7 {p:=0;for p<len(x)&&p<len(y)&&p<4&&x[p]==y[p]{p++};score+=float64(p)*0.1*(1-score)}
    return score
}
func suggest(value string, values []string) string {
    best:=""; score:=0.8
    for _,candidate:=range values {s:=similarity(value,candidate);if s>score{score=s;best=candidate}}
    return best
}
func unknownArgument(arg, command string, seen []string) {
    tip:=""
    similar:=""
    if strings.HasPrefix(arg,"--") {
        names:=[]string{};for _,s:=range specifications(command){names=append(names,s.long)}
        similar=suggest(strings.TrimPrefix(arg,"--"),names)
    }
    use:=usage(command)
    if similar!="" {
        tip="  tip: a similar argument exists: '--"+similar+"'\n\n"
        if command!="" {
            names:=append([]string{},seen...)
            already:=false;for _,n:=range names{if n==similar{already=true}}
            if !already{names=append(names,similar)}
            use=program+" "+command
            for _,n:=range names{use+=" --"+n}
            if command=="completions"{use+=" <SHELL>"}else{use+=" [INPUT]..."}
        }
    } else if command!="completions" && strings.HasPrefix(arg,"-") {
        tip="  tip: to pass '"+arg+"' as a value, use '-- "+arg+"'\n\n"
    }
    fmt.Fprintf(os.Stderr,"error: unexpected argument '%s' found\n\n%sUsage: %s\n\n%s",arg,tip,use,moreHelp)
    os.Exit(2)
}
func missingValue(name string, choices []string) {
    s:="a value is required for '"+name+"' but none was supplied"
    if len(choices)>0{s+="\n  [possible values: "+strings.Join(choices,", ")+"]"}
    cliError(s,"")
}
func enumValue(value, name string, choices []string, insensitive bool) string {
    for _,s:=range choices{if value==s || (insensitive && strings.EqualFold(value,s)){return s}}
    s:="invalid value '"+value+"' for '"+name+"'\n  [possible values: "+strings.Join(choices,", ")+"]"
    if candidate:=suggest(value,choices);candidate!=""{s+="\n\n  tip: a similar value exists: '"+candidate+"'"}
    cliError(s,"")
    return ""
}
func parse(args []string) options {
    o:=options{format:"binary", ignore:[]string{"/proc","/dev","/sys","/run"}}
    seen:=map[string]bool{}; seenOrder:=[]string{}; end:=false
    for pos:=0;pos<len(args);pos++ {
        arg:=args[pos]
        if !end && arg=="--" {end=true;continue}
        if !end && strings.HasPrefix(arg,"-") && arg!="-" {
            var tokens []string
            var attached *string
            isLong:=strings.HasPrefix(arg,"--")
            if isLong {
                name,value,has:=strings.Cut(arg[2:],"=");tokens=[]string{name};if has {attached=&value}
            } else {for _,c:=range arg[1:]{tokens=append(tokens,string(c))}}
            for ti:=0;ti<len(tokens);ti++ {
                token:=tokens[ti];spec:=optionSpec{};found:=false
                for _,s:=range specifications(o.command) { if (isLong && s.long==token) || (!isLong && s.short==token) {spec=s;found=true;break} }
                if !found {
                    a:="-"+token;if isLong{a="--"+token}
                    unknownArgument(a,o.command,seenOrder)
                }
                if seen[spec.long] && !spec.repeat {cliError("the argument '"+optionName(spec)+"' cannot be used multiple times",usage(o.command))}
                value:=""
                if spec.value!="" {
                    if !isLong && ti+1<len(tokens) {
