                case "help":printHelp(o.command,isLong);os.Exit(0)
                case "version":fmt.Println("dua "+version);os.Exit(0)
                case "threads":
                    v:=strings.TrimPrefix(value,"+")
                    parsed,err:=strconv.ParseUint(v,10,64)
