                        cliError("invalid value '"+value+"' for '--threads <THREADS>': "+detail,"")
                    }
                    o.threads=parsed
                case "format":o.format=enumValue(value,optionName(spec),formats,true)
                case "apparent-size":o.apparent=true
                case "count-hard-links":o.countLinks=true
                case "stay-on-filesystem":o.stay=true
                case "ignore-dirs":if !seen[spec.long]{o.ignore=nil};o.ignore=append(o.ignore,value)
                case "log-file":o.logFile=value;o.logSet=true
