func byteCount(size uint64, format string) string {
    switch format {
    case "bytes":return fmt.Sprintf("%10d b",size)
    case "gb":return fmt.Sprintf("%6.2f GB",float64(size)/1e9)
    case "gib":return fmt.Sprintf("%5.2f GiB",float64(size)/(1<<30))
    case "mb":return fmt.Sprintf("%8.2f MB",float64(size)/1e6)
    case "mib":return fmt.Sprintf("%7.2f MiB",float64(size)/(1<<20))
    }
    base:=float64(1024);units:=[]string{"  B","KiB","MiB","GiB","TiB","PiB","EiB"}
    if format=="metric"{base=1000;units=[]string{" B","KB","MB","GB","TB","PB","EB"}}
    unit:=0;value:=float64(size)
    for value>base && unit<len(units)-1{unit++;value/=base}
    if unit==0{return fmt.Sprintf("%7d %s",size,units[0])}
    return fmt.Sprintf("%7.2f %s",value,units[unit])
}

type statistics struct{entries,smallest,largest uint64}
