    // are entries in their own right, never traversal edges.
    var followed os.FileInfo
    var err error
    if root {
        followed,err=os.Stat(path)
        if err!=nil{n.errors=1;return n}
    }
    info,err:=os.Lstat(path)
    if err!=nil{n.errors=1;return n}
    n.valid=true;n.dir=info.IsDir();n.regular=info.Mode().IsRegular();n.link=info.Mode()&os.ModeSymlink!=0;n.modified=info.ModTime()
