        for _,entry:=range entries {
            p:=filepath.Join(path,entry.Name())
            child:=s.walk(p,entry.Name(),n,false,device)
            n.children=append(n.children,child)
            n.size+=child.size;n.entries+=child.entries;n.errors+=child.errors
