    fmt.Fprintf(&b,"    threads: %d,\n    format: %s,\n    apparent_size: %t,\n    count_hard_links: %t,\n    stay_on_filesystem: %t,\n    ignore_dirs: ",o.threads,form,o.apparent,o.countLinks,o.stay)
