func sgr(st textStyle)string {
    var b strings.Builder;b.WriteString("\x1b[0")
    if st.bold{b.WriteString(";1")};if st.reverse{b.WriteString(";7")};if st.underline{b.WriteString(";4")}
    if st.fg==16{b.WriteString(";38;2;176;126;0")}else if st.fg>=0{fmt.Fprintf(&b,";38;5;%d",st.fg)}
    if st.bg>=0{fmt.Fprintf(&b,";48;5;%d",st.bg)}
