func newUI(s *scanner) (*terminalUI,error) {
    implicit:=len(s.opts.inputs)==0
    if len(s.opts.inputs)==1{if st,e:=os.Stat(s.opts.inputs[0]);e==nil&&st.IsDir(){implicit=true}}
    paths,cwd,err:=s.prepareInputs();if err!=nil{return nil,err}
    root:=&node{name:cwd,path:cwd,dir:true,valid:true}
    for _,p:=range paths{
        n:=s.walk(p,p,root,true,0)
        if n.valid{root.children=append(root.children,n);root.entries+=n.entries;root.size+=n.size}
    }
    ui:=&terminalUI{scan:s,root:root,current:root,implicit:implicit,mode:"size",focus:"main",selections:map[*node]*node{},processed:s.stats.entries}
    return ui,nil
}
func (u *terminalUI) list() []*node {
    nodes:=append([]*node{},u.current.children...)
    if u.searchResults!=nil&&u.current==u.searchBase{nodes=append([]*node{},u.searchResults...)}
    sort.SliceStable(nodes,func(i,j int)bool {
        a,b:=nodes[i],nodes[j];cmp:=0
        switch u.mode {
        case "size":if a.size<b.size{cmp=-1}else if a.size>b.size{cmp=1}
        case "items":if a.entries<b.entries{cmp=-1}else if a.entries>b.entries{cmp=1}
        case "modified":if a.modified.Before(b.modified){cmp=-1}else if a.modified.After(b.modified){cmp=1}
        case "name":if a.dir!=b.dir{if a.dir{cmp=-1}else{cmp=1}}
        }
        if cmp==0{cmp=strings.Compare(a.name,b.name)}
        if u.ascending{return cmp<0};return cmp>0
    })
    if len(nodes)==0{u.selected=0}else if u.selected>=len(nodes){u.selected=len(nodes)-1}else if u.selected<0{u.selected=0}
    return nodes
}
func (u *terminalUI) selectedNode()*node {nodes:=u.list();if len(nodes)==0{return nil};return nodes[u.selected]}
