    ui.render()
    for {
        select {
        case sig:=<-signals:
            if sig!=syscall.SIGWINCH{return 0};ui.render()
        case data,ok:=<-input:
            if !ok{return 0}
            // Escape sequences can arrive in more than one read.
            if strings.HasSuffix(data,"\x1b")||strings.HasSuffix(data,"\x1b[")||strings.HasSuffix(data,"\x1bO"){
                select{case more,ok:=<-input:if ok{data+=more};case <-time.After(20*time.Millisecond):}
            }
            for _,key:=range decodeKeys(data){if ui.key(key){return 0}}
            ui.render()
        }
    }
}
