    left:=(width-1)/2;right:=width-1-left
    suffix:=[]rune(t);n:=0;i:=len(suffix)
    for i>0&&n+runeWidth(suffix[i-1])<=right{i--;n+=runeWidth(suffix[i])}
    return clipText(t,left)+"…"+string(suffix[i:])
}
func (s *screen) put(x,y int,r rune,style textStyle) {
    if x<0||y<0||x>=s.width||y>=s.height{return}
    s.cells[y*s.width+x]=cell{r:r,style:style}
}
func (s *screen) text(x,y int,t string,style textStyle,maxWidth int)int {
    start:=x
    for _,r:=range t {
        w:=runeWidth(r);if w==0{continue}
        if x-start+w>maxWidth||x+w>s.width{break}
        s.put(x,y,r,style)
        if w==2 && y>=0&&y<s.height&&x+1>=0{s.cells[y*s.width+x+1]=cell{r:' ',style:style,continuation:true}}
        x+=w
    }
    return x
}
func (s *screen) fill(x,y,w int,style textStyle) {for i:=0;i<w;i++{s.put(x+i,y,' ',style)}}
func sgr(st textStyle)string {
    var b strings.Builder;b.WriteString("\x1b[0")
    if st.bold{b.WriteString(";1")};if st.reverse{b.WriteString(";7")};if st.underline{b.WriteString(";4")}
    if st.fg==16{b.WriteString(";38;2;176;126;0")}else if st.fg>=0{fmt.Fprintf(&b,";38;5;%d",st.fg)}
    if st.bg>=0{fmt.Fprintf(&b,";48;5;%d",st.bg)}
    b.WriteByte('m');return b.String()
}
func (s *screen) draw() {
    var b strings.Builder
    prev:=textStyle{fg:-100,bg:-100}
    for y:=0;y<s.height;y++ {
        fmt.Fprintf(&b,"\x1b[%d;1H",y+1)
        for x:=0;x<s.width;x++ {
            c:=s.cells[y*s.width+x]
            if c.continuation{continue}
            if c.style!=prev{b.WriteString(sgr(c.style));prev=c.style}
            b.WriteRune(c.r)
        }
    }
    b.WriteString("\x1b[0m")
    os.Stderr.WriteString(b.String())
}
type rectangle struct{x,y,w,h int}
var navHint=" . = o|.. = u ── ⇊ = Ctrl+d|↓ = j|⇈ = Ctrl+u|↑ = k "
var markHint=" mark-move = d | mark-toggle = space | toggle-all = a "
func borderStyle(active bool)textStyle{s:=normal;if active{s.bold=true}else{s.fg=8};return s}
func drawBox(s *screen,r rectangle,title,hint,bottom string,active bool) {
    if r.w<2||r.h<2{return};st:=borderStyle(active)
    for x:=r.x+1;x<r.x+r.w-1;x++{s.put(x,r.y,'─',st);s.put(x,r.y+r.h-1,'─',st)}
    for y:=r.y+1;y<r.y+r.h-1;y++{s.put(r.x,y,'│',st);s.put(r.x+r.w-1,y,'│',st)}
    s.put(r.x,r.y,'┌',st);s.put(r.x+r.w-1,r.y,'┐',st);s.put(r.x,r.y+r.h-1,'└',st);s.put(r.x+r.w-1,r.y+r.h-1,'┘',st)
    tw:=textWidth(title);s.text(r.x+1,r.y,title,st,r.w-2)
    if hint!="" && tw+textWidth(hint)<=r.w-2{s.text(r.x+r.w-1-textWidth(hint),r.y,hint,st,textWidth(hint))}
    if bottom!="" && textWidth(bottom)<=r.w-2{s.text(r.x+r.w-1-textWidth(bottom),r.y+r.h-1,bottom,st,textWidth(bottom))}
}
func scrollbar(s *screen,r rectangle,count,position int,active bool,topOffset int) {
    height:=r.h-2-topOffset;if height<=0||count==0{return}
    thumb:=int(math.Round(float64(height*height)/float64(height+count-1)))
    if thumb<1{thumb=1};if thumb>height{thumb=height}
    start:=0
    if count>1{start=int(math.Round(float64(height-thumb)*float64(position)/float64(count-1)))}
    for i:=0;i<height;i++{ch:='║';if i>=start&&i<start+thumb{ch='█'};s.put(r.x+r.w-1,r.y+1+topOffset+i,ch,borderStyle(active))}
}

