type terminalUI struct {
    scan *scanner
    root,current *node
    implicit bool
    mode string
    ascending bool
    showCount,showTime bool
    barMode int
    selected,offset int
    selections map[*node]*node
    help bool
    helpOffset int
    focus string
    marked []*node
    markSelected int
    markActivated bool
    searchShown,searchCase bool
    query string
    searchResults []*node
    searchBase *node
    message string
    confirmExit bool
    width,height int
    processed uint64
}
func newUI(s *scanner) (*terminalUI,error) {
    implicit:=len(s.opts.inputs)==0
    if len(s.opts.inputs)==1{if st,e:=os.Stat(s.opts.inputs[0]);e==nil&&st.IsDir(){implicit=true}}
    paths,cwd,err:=s.prepareInputs();if err!=nil{return nil,err}
    root:=&node{name:cwd,path:cwd,dir:true,valid:true}
    for _,p:=range paths{
        n:=s.walk(p,p,root,true,0)
        if n.valid{root.children=append(root.children,n);root.entries+=n.entries;root.size+=n.size}
    }
    ui:=&terminalUI{scan:s,root:root,current:root,implicit:implicit,mode:"size",focus:"main",selections:map[*node]*node{},processed:s.stats.entries}
    return ui,nil
}
func (u *terminalUI) list() []*node {
    nodes:=append([]*node{},u.current.children...)
    if u.searchResults!=nil&&u.current==u.searchBase{nodes=append([]*node{},u.searchResults...)}
    sort.SliceStable(nodes,func(i,j int)bool {
        a,b:=nodes[i],nodes[j];cmp:=0
        switch u.mode {
        case "size":if a.size<b.size{cmp=-1}else if a.size>b.size{cmp=1}
        case "items":if a.entries<b.entries{cmp=-1}else if a.entries>b.entries{cmp=1}
        case "modified":if a.modified.Before(b.modified){cmp=-1}else if a.modified.After(b.modified){cmp=1}
        case "name":if a.dir!=b.dir{if a.dir{cmp=-1}else{cmp=1}}
        }
        if cmp==0{cmp=strings.Compare(a.name,b.name)}
        if u.ascending{return cmp<0};return cmp>0
    })
    if len(nodes)==0{u.selected=0}else if u.selected>=len(nodes){u.selected=len(nodes)-1}else if u.selected<0{u.selected=0}
    return nodes
}
func (u *terminalUI) selectedNode()*node {nodes:=u.list();if len(nodes)==0{return nil};return nodes[u.selected]}
func (u *terminalUI) selectNode(n *node) {
    for i,v:=range u.list(){if v==n{u.selected=i;return}}
    u.selected=0
}
func (u *terminalUI) setSort(mode string) {
    n:=u.selectedNode()
    if u.mode==mode{u.ascending=!u.ascending}else{u.mode=mode;u.ascending=mode=="name"}
    u.selectNode(n)
}
func (u *terminalUI) hasMark(n *node)bool {for _,v:=range u.marked{if n==v{return true}};return false}
func (u *terminalUI) isMarked(n *node)bool {
    for p:=n;p!=nil;p=p.parent{if u.hasMark(p){return true}}
    return false
}
func (u *terminalUI) removeMark(n *node) {
    for i,v:=range u.marked{if n==v{u.marked=append(u.marked[:i],u.marked[i+1:]...);break}}
    if u.markSelected>=len(u.marked){u.markSelected=len(u.marked)-1}
    if len(u.marked)==0{u.markSelected=0;u.focus="main";u.markActivated=false}
}
func (u *terminalUI) toggleMark(n *node,onlyAdd bool) {
    if n==nil{return}
    if u.hasMark(n){if !onlyAdd{u.removeMark(n)}}else{u.marked=append(u.marked,n)}
}
func shortBytes(size uint64,format string)string{return strings.TrimLeft(byteCount(size,format)," ")}
func bar(value float64,width int)string {
    parts:=int(math.Round(value*float64(width)*8));if parts<0{parts=0};if parts>width*8{parts=width*8}
    text:=strings.Repeat("█",parts/8);n:=parts/8
    if parts%8>0{runes:=[]rune(" ▏▎▍▌▋▊▉");text+=string(runes[parts%8]);n++}
    return text+strings.Repeat(" ",width-n)
}
func (u *terminalUI) drawMain(s *screen,r rectangle) {
    nodes:=u.list();total,entries:=uint64(0),uint64(0)
    for _,n:=range nodes{total+=n.size;entries+=n.entries}
    title:=fmt.Sprintf(" %s (%d visible, %d total, %s) ",utf8Path(u.current.path),len(nodes),entries,shortBytes(total,u.scan.opts.format))
    hint,bottom:="","";active:=u.focus=="main"
    if active{hint=navHint;bottom=markHint}
    drawBox(s,r,title,hint,bottom,active)
    height:=r.h-2
    if height<1{return}
    if u.selected<u.offset{u.offset=u.selected};if u.selected>=u.offset+height{u.offset=u.selected-height+1}
    if u.offset>len(nodes)-1{u.offset=0}
    for i:=0;i<height && i+u.offset<len(nodes);i++ {
        index:=i+u.offset;n:=nodes[index];rowStyle:=normal
        if active && index==u.selected{rowStyle.reverse=true}
        x,y:=r.x+1,r.y+1+i;max:=r.x+r.w-1
        s.fill(x,y,r.w-2,rowStyle)
        green:=rowStyle;green.fg=2
        if u.showTime || u.mode=="modified"{
            x=s.text(x,y," "+n.modified.Local().Format("02/01/2006 15:04:05")+" | ",rowStyle,max-x)
        }
        x=s.text(x,y,byteCount(n.size,u.scan.opts.format),green,max-x)
        x=s.text(x,y," | ",rowStyle,max-x)
        fraction:=0.0;if total>0{fraction=float64(n.size)/float64(total)}
        switch u.barMode {
        case 0:x=s.text(x,y,fmt.Sprintf("%6.1f%%  ",fraction*100)+bar(fraction,10),rowStyle,max-x)
        case 1:x=s.text(x,y,fmt.Sprintf("%6.1f%% ",fraction*100),rowStyle,max-x)
        case 2:x=s.text(x,y,bar(fraction,10),rowStyle,max-x)
        case 3:x=s.text(x,y,bar(fraction,19),rowStyle,max-x)
        }
        x=s.text(x,y," | ",rowStyle,max-x)
        if u.showCount || u.mode=="items" {
            count:="    ";if len(n.children)>0{count=fmt.Sprintf("%4d",n.entries)}
            x=s.text(x,y,count+" | ",rowStyle,max-x)
        }
        name:=n.name
        if u.searchResults!=nil&&u.current==u.searchBase{
            if rel,err:=filepath.Rel(u.current.path,n.path);err==nil{name=rel}
            if !filepath.IsAbs(n.path)&&u.current==u.root{name=n.path}
            name=" "+name
        }else if n.dir && !n.link {
            if !strings.HasPrefix(name,"/"){name="/"+name}
        }else{name=" "+name}
        name=utf8Path(name)
        nameStyle:=rowStyle
        if n.dir&&!n.link{nameStyle.fg=6}
        if u.isMarked(n){nameStyle.fg=16;name=middleClip(name,max-x-1)}
        if !u.scan.opts.noEntryCheck{if _,e:=os.Lstat(n.path);e!=nil{nameStyle.fg=1}}
        s.text(x,y,name,nameStyle,max-x)
    }
    scrollbar(s,r,len(nodes),u.selected,active,0)
}
func (u *terminalUI) drawHelp(s *screen,r rectangle) {
    hint:="";if u.focus=="help"{hint=navHint}
    drawBox(s,r,"Help",hint,"",u.focus=="help")
    maxOffset:=len(helpLines)-(r.h-2);if maxOffset<0{maxOffset=0}
    if u.helpOffset>maxOffset{u.helpOffset=maxOffset};if u.helpOffset<0{u.helpOffset=0}
    for i:=0;i<r.h-2&&i+u.helpOffset<len(helpLines);i++{s.text(r.x+1,r.y+1+i,helpLines[i+u.helpOffset],normal,r.w-2)}
}
func (u *terminalUI) drawMarked(s *screen,r rectangle) {
    total,count:=uint64(0),uint64(0)
    for _,n:=range u.marked{total+=n.size;count+=n.entries}
    title:=fmt.Sprintf("Marked %d items (%s) ",count,shortBytes(total,u.scan.opts.format))
    bottom:="";if u.focus=="marked"||u.markActivated{bottom=" mark-toggle = space,d | remove-all = a"}
    drawBox(s,r,title,"",bottom,u.focus=="marked")
    offset:=0
    if u.markActivated{
        prompt:=" Ctrl + t  to trash or  Ctrl + r  to delete without prompt"
        s.text(r.x+1,r.y+1,prompt,normal,r.w-2);offset=1
    }
    height:=r.h-2-offset;start:=0
    if u.markSelected>=height{start=u.markSelected-height+1}
    for i:=0;i<height&&i+start<len(u.marked);i++{
        n:=u.marked[i+start];y:=r.y+1+offset+i;st:=normal
        if u.focus=="marked"&&i+start==u.markSelected{st.reverse=true}
        s.fill(r.x+1,y,r.w-2,st)
        size:=byteCount(n.size,u.scan.opts.format)
        name:=" "+utf8Path(n.path)
        ns:=st;ns.fg=16
        sizeX:=r.x+r.w-3-textWidth(size)
        s.text(r.x+1,y,middleClip(name,sizeX-r.x-1),ns,sizeX-r.x-1)
        ss:=st;ss.fg=2;s.text(sizeX,y,size,ss,textWidth(size))
    }
    scrollbar(s,r,len(u.marked),u.markSelected,u.focus=="marked",offset)
}
func (u *terminalUI) render() {
    w,h:=dimensions();u.width=w;u.height=h
    if w<2||h<4{return}
    s:=newScreen(w,h)
    head:=textStyle{fg:0,bg:15}
    s.fill(0,0,w,head)
    s.text(0,0," Disk Usage Analyzer v"+version+"    (press ? for help)",head,w)
    for _,x:=range []int{1,6,12}{if x<w{s.cells[x].style.bold=true}}
    for x:=30;x<50&&x<w;x++{s.cells[x].style.underline=true}
    bodyH:=h-2;mainW:=w
    if u.help||len(u.marked)>0{mainW=w/2}
    mainH:=bodyH;if u.searchShown{mainH-=3}
    u.drawMain(s,rectangle{0,1,mainW,mainH})
    if u.searchShown {
        title:="Git-Glob (case-insensitive)";if u.searchCase{title="Git-Glob (case-sensitive)"}
        hint:="";if u.focus=="search"{hint=" search = enter | case = ^f | cancel = esc "}
        r:=rectangle{0,1+mainH,mainW,3}
        drawBox(s,r,title,hint,"",u.focus=="search")
        s.text(1,r.y+1," "+u.query,normal,r.w-2)
    }
    if u.help&&len(u.marked)>0 {
        top:=bodyH/2
        u.drawHelp(s,rectangle{mainW,1,w-mainW,top})
        u.drawMarked(s,rectangle{mainW,1+top,w-mainW,bodyH-top})
    }else if u.help{u.drawHelp(s,rectangle{mainW,1,w-mainW,bodyH})}else if len(u.marked)>0{u.drawMarked(s,rectangle{mainW,1,w-mainW,bodyH})}
    order:="descending";if u.ascending{order="ascending"}
    status:=fmt.Sprintf("Sort mode: %s %s  Total disk usage: %s  Processed %d entries in 0.00s",u.mode,order,shortBytes(u.root.size,u.scan.opts.format),u.processed)
    if u.message!=""{status+="  "+u.message}
    if u.confirmExit{status="Press esc or q again to exit..."}
    foot:=normal;foot.reverse=true;s.text(0,h-1,status,foot,w)
    s.draw()
}
func (u *terminalUI) move(delta int) {
    switch u.focus {
    case "help":u.helpOffset+=delta
    case "marked":
        u.markSelected+=delta;if u.markSelected<0{u.markSelected=0};if u.markSelected>=len(u.marked){u.markSelected=len(u.marked)-1}
    default:
        u.selected+=delta;if u.selected<0{u.selected=0};nodes:=u.list();if u.selected>=len(nodes)&&len(nodes)>0{u.selected=len(nodes)-1}
    }
}
func (u *terminalUI) descend() {
    n:=u.selectedNode()
    if n==nil||len(n.children)==0{u.message="Entry is a file or an empty directory";return}
    u.selections[u.current]=n;u.current=n;u.selected=0;u.offset=0
    if n:=u.selections[u.current];n!=nil{u.selectNode(n)}
}
func (u *terminalUI) ascend() {
    if u.current==u.root{u.message="Top level reached";return}
    old:=u.current;u.current=old.parent
    if u.current==nil{u.current=u.root};u.offset=0;u.selectNode(old)
}
func (u *terminalUI) cycleFocus() {
    panes:=[]string{"main"};if u.help{panes=append(panes,"help")};if len(u.marked)>0{panes=append(panes,"marked")};if u.searchShown{panes=append(panes,"search")}
    for i,p:=range panes{if p==u.focus{u.focus=panes[(i+1)%len(panes)];break}}
    if u.focus=="marked"{u.markActivated=true}
}
func (u *terminalUI) closeSearch() {
    u.focus="main";u.searchShown=false;u.searchResults=nil;u.searchBase=nil;u.selected=0;u.offset=0
}
func (u *terminalUI) search() {
    base:=u.searchBase;if base==nil{base=u.current;u.searchBase=base}
    pattern:=u.query;if !u.searchCase{pattern=strings.ToLower(pattern)}
    pattern=strings.TrimPrefix(pattern,"/")
    matches:=[]*node{}
    var visit func(*node,string)
    visit=func(n *node,relative string){
        name:=relative;pat:=pattern
        if !u.searchCase{name=strings.ToLower(name)}
        target:=name
        if !strings.Contains(pat,"/"){target=filepath.Base(name)}
        for strings.HasPrefix(pat,"**/"){pat=pat[3:];if !strings.Contains(pat,"/"){target=filepath.Base(name)}}
        matched,_:=filepath.Match(pat,target)
        if matched{matches=append(matches,n);return}
        for _,c:=range n.children{visit(c,relative+"/"+c.name)}
    }
    for _,n:=range base.children{visit(n,n.name)}
    if len(matches)==0{u.message="No match found";return}
    u.searchResults=matches;u.current=base;u.selected=0;u.offset=0;u.focus="main"
}
func recalculate(n *node) {
    n.size=n.ownSize;n.entries=1
    for _,c:=range n.children{recalculate(c);n.size+=c.size;n.entries+=c.entries}
}
func (u *terminalUI) deleteMarked(trash bool) {
    keep:=[]*node{}
    for _,n:=range u.marked{
        var err error
        if trash {
            data:=os.Getenv("XDG_DATA_HOME");if data==""{home,_:=os.UserHomeDir();data=filepath.Join(home,".local","share")}
            files:=filepath.Join(data,"Trash","files");info:=filepath.Join(data,"Trash","info")
            err=os.MkdirAll(files,0700);if err==nil{err=os.MkdirAll(info,0700)}
            name:=filepath.Base(n.path)
            if err==nil {
                original,_:=filepath.Abs(n.path);dest:=filepath.Join(files,name)
                for i:=1;;i++{if _,e:=os.Lstat(dest);os.IsNotExist(e){break};name=fmt.Sprintf("%s.%d",filepath.Base(n.path),i);dest=filepath.Join(files,name)}
                err=os.Rename(n.path,dest)
                if err==nil{os.WriteFile(filepath.Join(info,name+".trashinfo"),[]byte("[Trash Info]\nPath="+original+"\nDeletionDate="+time.Now().Format("2006-01-02T15:04:05")+"\n"),0600)}
            }
        }else{err=os.RemoveAll(n.path)}
        if err!=nil{keep=append(keep,n);u.message=errorText(err);continue}
        if n.parent!=nil{for i,c:=range n.parent.children{if c==n{n.parent.children=append(n.parent.children[:i],n.parent.children[i+1:]...);break}}}
    }
    u.marked=keep
    recalculate(u.root);u.root.entries--
    if len(keep)==0{u.focus="main";u.markSelected=0;u.markActivated=false}
    u.searchResults=nil;u.selected=0;u.offset=0
}
func (u *terminalUI) refresh(all bool) {
    target:=u.current;if !all{target=u.selectedNode();if target==nil{return}}
    scan:=newScanner(u.scan.opts)
    if target==u.root {
        children:=[]*node{}
        if u.implicit {
            entries,e:=os.ReadDir(".");if e!=nil{u.message=errorText(e);return}
            for _,entry:=range entries{if entry.Type()&os.ModeSymlink!=0{continue};n:=scan.walk(entry.Name(),entry.Name(),u.root,true,0);if n.valid{children=append(children,n)}}
        }else{for _,child:=range u.root.children{n:=scan.walk(child.path,child.name,u.root,true,0);if n.valid{children=append(children,n)}}}
        u.root.children=children
    }else{
        n:=scan.walk(target.path,target.name,target.parent,true,0)
        if target.parent!=nil{
            for i,c:=range target.parent.children{if c==target{target.parent.children[i]=n;break}}
        }
        if u.current==target{u.current=n}
    }
    recalculate(u.root);u.root.entries--;u.processed=scan.stats.entries
    u.selected=0;u.offset=0;u.searchResults=nil;u.marked=nil;u.markSelected=0;u.markActivated=false
}
func (u *terminalUI) key(key string)bool {
    if key=="ctrl-c"{return true}
    wasConfirm:=u.confirmExit;u.confirmExit=false;u.message=""
    if u.focus=="search" {
        switch key {
        case "esc":u.closeSearch()
        case "enter":u.search()
        case "tab":u.cycleFocus()
        case "ctrl-f":u.searchCase=!u.searchCase
        case "backspace":r:=[]rune(u.query);if len(r)>0{u.query=string(r[:len(r)-1])}
        case "ctrl-u":u.query=""
        default:if utf8.RuneCountInString(key)==1{u.query+=key}
        }
        return false
    }
    switch key {
    case "q","esc":
        switch u.focus {
        case "help":u.help=false;u.focus="main"
        case "marked":u.focus="main"
        default:
            if u.searchShown{u.closeSearch()}else if len(u.marked)>0&&!wasConfirm{u.confirmExit=true}else{return true}
        }
        return false
    case "?":u.help=!u.help;if u.help{u.focus="help"}else{u.focus="main"};return false
    case "tab","backtab":u.cycleFocus();return false
    case "j","down":u.move(1);return false
    case "k","up":u.move(-1);return false
    case "ctrl-d","pagedown":u.move(10);return false
    case "ctrl-u","pageup":u.move(-10);return false
    case "H","home":u.move(-1<<30);return false
    case "G","end":u.move(1<<30);return false
    }
    if u.focus=="help"{return false}
    if u.focus=="marked" {
        switch key {
        case "x","d"," ":if len(u.marked)>0{u.removeMark(u.marked[u.markSelected])}
        case "a":u.marked=nil;u.markActivated=false;u.markSelected=0;u.focus="main"
        case "ctrl-r":u.deleteMarked(false)
        case "ctrl-t":u.deleteMarked(true)
        }
        return false
    }
    switch key {
    case "o","l","enter","right":u.descend()
    case "u","h","left","backspace":u.ascend()
    case "s":u.setSort("size")
    case "n":u.setSort("name")
    case "c":u.setSort("items")
    case "m":u.setSort("modified")
    case "C":u.showCount=!u.showCount
    case "M":u.showTime=!u.showTime
    case "g","S":u.barMode=(u.barMode+1)%4
    case " ":u.toggleMark(u.selectedNode(),false)
    case "d":u.toggleMark(u.selectedNode(),false);u.move(1)
    case "x":u.toggleMark(u.selectedNode(),true);u.move(1)
    case "a":
        nodes:=u.list();all:=len(nodes)>0
        for _,n:=range nodes{if !u.hasMark(n){all=false;break}}
        for _,n:=range nodes{if all{u.removeMark(n)}else if !u.hasMark(n){u.toggleMark(n,true)}}
    case "/":u.searchShown=true;u.focus="search";if u.searchBase==nil{u.searchBase=u.current}
    case "r":u.refresh(false)
    case "R":u.refresh(true)
    }
    return false
}
func decodeKeys(data string)[]string {
    keys:=[]string{}
    sequences:=map[string]string{"\x1b[A":"up","\x1b[B":"down","\x1b[C":"right","\x1b[D":"left","\x1b[H":"home","\x1b[F":"end","\x1bOA":"up","\x1bOB":"down","\x1bOC":"right","\x1bOD":"left","\x1bOH":"home","\x1bOF":"end","\x1b[1~":"home","\x1b[4~":"end","\x1b[5~":"pageup","\x1b[6~":"pagedown","\x1b[7~":"home","\x1b[8~":"end","\x1b[Z":"backtab"}
    for len(data)>0 {
        found:=false
        if data[0]==27 {
            for seq,key:=range sequences{if strings.HasPrefix(data,seq){keys=append(keys,key);data=data[len(seq):];found=true;break}}
            if found{continue}
        }
        r,n:=utf8.DecodeRuneInString(data);data=data[n:]
        key:=string(r)
        switch r {
        case 3:key="ctrl-c";case 4:key="ctrl-d";case 6:key="ctrl-f";case 18:key="ctrl-r";case 20:key="ctrl-t";case 21:key="ctrl-u"
        case 9:key="tab";case 10,13:key="enter";case 27:key="esc";case 8,127:key="backspace"
        }
        keys=append(keys,key)
    }
    return keys
}
func runTerminal(s *scanner)int {
    ui,err:=newUI(s);if err!=nil{fmt.Fprintln(os.Stderr,"Error: "+errorText(err));return 1}
    tty,err:=os.OpenFile("/dev/tty",os.O_RDWR,0)
    if err!=nil{tty=os.Stderr}else{defer tty.Close()}
    old,err:=terminalAttributes(tty.Fd());if err!=nil{fmt.Fprintln(os.Stderr,"Error: "+errorText(err));return 1}
    raw:=*old
    raw.Iflag &^= syscall.IGNBRK|syscall.BRKINT|syscall.PARMRK|syscall.ISTRIP|syscall.INLCR|syscall.IGNCR|syscall.ICRNL|syscall.IXON
    raw.Oflag &^= syscall.OPOST
    raw.Lflag &^= syscall.ECHO|syscall.ECHONL|syscall.ICANON|syscall.ISIG|syscall.IEXTEN
    raw.Cflag &^= syscall.CSIZE|syscall.PARENB;raw.Cflag|=syscall.CS8
    raw.Cc[syscall.VMIN]=1;raw.Cc[syscall.VTIME]=0
    if err:=ioctl(tty.Fd(),syscall.TCSETS,unsafe.Pointer(&raw));err!=nil{fmt.Fprintln(os.Stderr,"Error: "+errorText(err));return 1}
    defer ioctl(tty.Fd(),syscall.TCSETS,unsafe.Pointer(old))
    os.Stderr.WriteString("\x1b[?1049h\x1b[?25l\x1b[2J")
    defer os.Stderr.WriteString("\x1b[0m\x1b[?25h\x1b[?1049l")
    signals:=make(chan os.Signal,4);signal.Notify(signals,syscall.SIGWINCH,syscall.SIGINT,syscall.SIGTERM);defer signal.Stop(signals)
    input:=make(chan string,16)
    go func(){buf:=make([]byte,256);for{n,e:=tty.Read(buf);if n>0{input<-string(buf[:n])};if e!=nil{close(input);return}}}()
    ui.render()
    for {
        select {
        case sig:=<-signals:
            if sig!=syscall.SIGWINCH{return 0};ui.render()
        case data,ok:=<-input:
            if !ok{return 0}
            // Escape sequences can arrive in more than one read.
            if strings.HasSuffix(data,"\x1b")||strings.HasSuffix(data,"\x1b[")||strings.HasSuffix(data,"\x1bO"){
                select{case more,ok:=<-input:if ok{data+=more};case <-time.After(20*time.Millisecond):}
            }
            for _,key:=range decodeKeys(data){if ui.key(key){return 0}}
            ui.render()
        }
    }
}
EOF
