func TestByteCount(t *testing.T) {
    cases:=[]struct{size uint64;format,want string}{
        {0,"binary","      0   B"},
        {1024,"binary","   1024   B"},
        {1025,"binary","   1.00 KiB"},
        {1048576,"binary","1024.00 KiB"},
        {1048577,"binary","   1.00 MiB"},
        {1000,"metric","   1000  B"},
        {1001,"metric","   1.00 KB"},
        {1000000,"metric","1000.00 KB"},
        {1000001,"metric","   1.00 MB"},
        {123,"bytes","       123 b"},
        {1000000,"mb","     1.00 MB"},
        {1048576,"mib","    1.00 MiB"},
        {1000000000,"gb","   1.00 GB"},
        {1073741824,"gib","  1.00 GiB"},
    }
    for _,c:=range cases{if got:=byteCount(c.size,c.format);got!=c.want{t.Errorf("%s(%d): got %q, want %q",c.format,c.size,got,c.want)}}
}

func TestHardLinksAndStatistics(t *testing.T) {
    dir:=t.TempDir();first:=filepath.Join(dir,"first");second:=filepath.Join(dir,"second")
    if err:=os.WriteFile(first,[]byte(strings.Repeat("x",73)),0600);err!=nil{t.Fatal(err)}
