    s:=newScanner(options{apparent:true})
    for i,path:=range []string{first,second,first,second}{
        n:=s.walk(path,path,nil,true,0);want:=uint64(0);if i%2==0{want=73}
        if n.size!=want{t.Errorf("visit %d got %d, want %d",i,n.size,want)}
    }
    if s.stats.entries!=4||s.stats.smallest!=0||s.stats.largest!=73{t.Errorf("incorrect statistics: %s",s.stats)}
    s=newScanner(options{apparent:true,countLinks:true})
    for _,path:=range []string{first,second}{if n:=s.walk(path,path,nil,true,0);n.size!=73{t.Errorf("hard-link counting got %d",n.size)}}
}

func TestTraversalAndIgnores(t *testing.T) {
    dir:=t.TempDir();sub:=filepath.Join(dir,"sub")
    if err:=os.Mkdir(sub,0700);err!=nil{t.Fatal(err)}
    file:=filepath.Join(sub,"data");if err:=os.WriteFile(file,[]byte("12345"),0600);err!=nil{t.Fatal(err)}
    link:=filepath.Join(dir,"link");if err:=os.Symlink("sub",link);err!=nil{t.Fatal(err)}
    broken:=filepath.Join(dir,"broken");if err:=os.Symlink("missing",broken);err!=nil{t.Fatal(err)}
    s:=newScanner(options{apparent:true})
    n:=s.walk(dir,dir,nil,true,0)
    ds,_:=os.Stat(dir);ss,_:=os.Stat(sub)
    want:=uint64(ds.Size()+ss.Size()+5+3+7)
    if n.size!=want||n.entries!=5||n.errors!=0{t.Errorf("tree: got %d bytes, %d entries, %d errors",n.size,n.entries,n.errors)}
    s=newScanner(options{apparent:true,ignore:[]string{sub}})
    n=s.walk(dir,dir,nil,true,0)
    if n.size!=want-5||n.entries!=4{t.Errorf("ignored directory: %d bytes, %d entries",n.size,n.entries)}
    s=newScanner(options{apparent:true})
    n=s.walk(broken,broken,nil,true,0)
    if n.valid||n.errors!=1||s.stats.entries!=0{t.Errorf("broken root: %+v",n)}
}

